solution:
const seuil = Number(input("Seuil ?"));
const ateliers = [{id:"a",places:0},{id:"b",places:2},{id:"c",places:5}];
const selection = [];
for (const atelier of ateliers) { if (atelier.places >= seuil) { selection.push(atelier); } }
console.log(selection.length);

