starter_code:
const id = input("Identifiant ?");
const ateliers = [{id:"a",titre:"Semis"},{id:"b",titre:"Compost"}];
let trouve = null;
console.log("Introuvable");

solution:
const id = input("Identifiant ?");
const ateliers = [{id:"a",titre:"Semis"},{id:"b",titre:"Compost"}];
let trouve = null;
for (const atelier of ateliers) { if (atelier.id === id) { trouve = atelier; } }
if (trouve !== null) { console.log("Trouvé"); } else { console.log("Introuvable"); }

